syntax = "proto3";
package neumann.v1;

// Query service for executing Neumann queries.
service QueryService {
  // Execute a single query.
  rpc Execute(QueryRequest) returns (QueryResponse);
  // Execute a query with streaming results (for large result sets).
  rpc ExecuteStream(QueryRequest) returns (stream QueryResponseChunk);
  // Execute multiple queries in a batch.
  rpc ExecuteBatch(BatchQueryRequest) returns (BatchQueryResponse);
  // Execute a paginated query with cursor-based navigation.
  rpc ExecutePaginated(PaginatedQueryRequest) returns (PaginatedQueryResponse);
  // Close a cursor to free server resources.
  rpc CloseCursor(CloseCursorRequest) returns (CloseCursorResponse);
}

// Blob service for artifact storage.
service BlobService {
  // Upload a blob with streaming chunks.
  rpc Upload(stream BlobUploadRequest) returns (BlobUploadResponse);
  // Download a blob with streaming chunks.
  rpc Download(BlobDownloadRequest) returns (stream BlobDownloadChunk);
  // Delete a blob.
  rpc Delete(BlobDeleteRequest) returns (BlobDeleteResponse);
  // Get artifact metadata.
  rpc GetMetadata(BlobMetadataRequest) returns (ArtifactInfo);
}

// Health check service.
service Health {
  // Check server health.
  rpc Check(HealthCheckRequest) returns (HealthCheckResponse);
}

// === Query Messages ===

message QueryRequest {
  string query = 1;
  // Optional identity for vault access control.
  optional string identity = 2;
}

message QueryResponse {
  oneof result {
    EmptyResult empty = 1;
    StringValue value = 2;
    CountResult count = 3;
    IdsResult ids = 4;
    RowsResult rows = 5;
    NodesResult nodes = 6;
    EdgesResult edges = 7;
    PathResult path = 8;
    SimilarResult similar = 9;
    UnifiedQueryResult unified = 10;
    TableListResult table_list = 11;
    BlobResult blob = 12;
    ArtifactInfo artifact_info = 13;
    ArtifactListResult artifact_list = 14;
    BlobStatsResult blob_stats = 15;
    CheckpointListResult checkpoint_list = 16;
    ChainQueryResult chain = 17;
    PageRankResult page_rank = 18;
    CentralityResult centrality = 19;
    CommunitiesResult communities = 21;
    ConstraintsResult constraints = 22;
    AggregateResult aggregate = 23;
    BatchOperationResult batch_operation = 24;
    GraphIndexesResult graph_indexes = 25;
    PatternMatchResult pattern_match = 26;
    SpatialQueryResult spatial = 27;
  }
  optional ErrorInfo error = 20;
}

message QueryResponseChunk {
  oneof chunk {
    RowChunk row = 1;
    NodeChunk node = 2;
    EdgeChunk edge = 3;
    SimilarChunk similar_item = 4;
    bytes blob_data = 5;
    SpatialChunk spatial_item = 6;
    ErrorInfo error = 10;
    StreamCursorInfo cursor_info = 11;
  }
  bool is_final = 15;
  // Sequence number for ordering (for cursor checkpoint).
  optional uint64 sequence_number = 16;
}

// Cursor checkpoint info sent during streaming.
message StreamCursorInfo {
  // Cursor token for resuming the stream.
  string cursor = 1;
  // Number of items sent so far.
  uint64 items_sent = 2;
  // Total count of items (if known).
  optional uint64 total_count = 3;
}

message BatchQueryRequest {
  repeated QueryRequest queries = 1;
}

message BatchQueryResponse {
  repeated QueryResponse results = 1;
}

// Paginated query request with cursor support.
message PaginatedQueryRequest {
  // The query to execute.
  string query = 1;
  // Optional identity for vault access control.
  optional string identity = 2;
  // Cursor token to resume from (omit for first page).
  optional string cursor = 3;
  // Number of items per page (default: 100).
  optional uint32 page_size = 4;
  // Whether to count total results (may be expensive).
  optional bool count_total = 5;
  // Custom TTL for the cursor in seconds (default: 300).
  optional uint32 cursor_ttl_secs = 6;
}

// Paginated query response with cursor tokens.
message PaginatedQueryResponse {
  // The query result for the current page.
  QueryResponse result = 1;
  // Cursor token for the next page (absent if last page).
  optional string next_cursor = 2;
  // Cursor token for the previous page (absent if first page).
  optional string prev_cursor = 3;
  // Total count of results (if requested and available).
  optional uint64 total_count = 4;
  // Whether there are more results after this page.
  bool has_more = 5;
  // Number of items in this page.
  uint32 page_size = 6;
}

// Request to close a cursor.
message CloseCursorRequest {
  // The cursor token to close.
  string cursor = 1;
}

// Response to closing a cursor.
message CloseCursorResponse {
  // True if cursor was found and closed.
  bool success = 1;
}

// === Result Types ===

message EmptyResult {}

message StringValue {
  string value = 1;
}

message CountResult {
  uint64 count = 1;
}

message IdsResult {
  repeated uint64 ids = 1;
}

message RowsResult {
  repeated Row rows = 1;
}

message Row {
  uint64 id = 1;
  repeated ColumnValue values = 2;
}

message ColumnValue {
  string name = 1;
  Value value = 2;
}

message Value {
  oneof kind {
    bool null = 1;
    int64 int_value = 2;
    double float_value = 3;
    string string_value = 4;
    bool bool_value = 5;
  }
}

message NodesResult {
  repeated Node nodes = 1;
}

message Node {
  uint64 id = 1;
  string label = 2;
  map<string, string> properties = 3;
}

message NodeChunk {
  Node node = 1;
}

message EdgesResult {
  repeated Edge edges = 1;
}

message Edge {
  uint64 id = 1;
  uint64 from = 2;
  uint64 to = 3;
  string label = 4;
}

message EdgeChunk {
  Edge edge = 1;
}

message PathResult {
  repeated uint64 node_ids = 1;
}

message SimilarResult {
  repeated SimilarItem items = 1;
}

message SimilarItem {
  string key = 1;
  float score = 2;
}

message SimilarChunk {
  SimilarItem item = 1;
}

message SpatialChunk {
  SpatialItem item = 1;
}

// === Graph Algorithm Result Types ===

// Centrality algorithm type.
enum CentralityType {
  CENTRALITY_TYPE_UNSPECIFIED = 0;
  CENTRALITY_TYPE_BETWEENNESS = 1;
  CENTRALITY_TYPE_CLOSENESS = 2;
  CENTRALITY_TYPE_EIGENVECTOR = 3;
}

message PageRankResult {
  repeated PageRankItem items = 1;
  // Algorithm metadata.
  optional uint32 iterations = 2;
  optional double convergence = 3;
  optional bool converged = 4;
}

message PageRankItem {
  uint64 node_id = 1;
  double score = 2;
}

message CentralityResult {
  repeated CentralityItem items = 1;
  // Algorithm metadata.
  optional CentralityType centrality_type = 2;
  optional uint32 iterations = 3;
  optional bool converged = 4;
  optional uint32 sample_count = 5;
}

message CentralityItem {
  uint64 node_id = 1;
  double score = 2;
}

// === Additional Graph Result Types ===

message CommunitiesResult {
  repeated CommunityItem items = 1;
  // Algorithm metadata.
  optional uint32 community_count = 2;
  optional double modularity = 3;
  optional uint32 passes = 4;
  optional uint32 iterations = 5;
  // Full community membership lists.
  repeated CommunityMemberList communities = 6;
}

message CommunityItem {
  uint64 node_id = 1;
  uint64 community_id = 2;
}

// List of members for a community.
message CommunityMemberList {
  uint64 community_id = 1;
  repeated uint64 member_node_ids = 2;
}

message ConstraintsResult {
  repeated ConstraintItem items = 1;
}

message ConstraintItem {
  string name = 1;
  string target = 2;
  string property = 3;
  string constraint_type = 4;
}

message AggregateResult {
  oneof value {
    uint64 count = 1;
    double sum = 2;
    double avg = 3;
    double min = 4;
    double max = 5;
  }
}

message BatchOperationResult {
  string operation = 1;
  uint64 affected_count = 2;
  repeated uint64 created_ids = 3;
}

message GraphIndexesResult {
  repeated string indexes = 1;
}

// Pattern Match types (preserves full match data)
message PatternMatchResult {
  repeated PatternMatchBinding matches = 1;
  PatternMatchStats stats = 2;
}

message PatternMatchBinding {
  repeated BindingEntry bindings = 1;
}

message BindingEntry {
  string variable = 1;
  BindingValue value = 2;
}

message BindingValue {
  oneof value {
    NodeBinding node = 1;
    EdgeBinding edge = 2;
    PathBinding path = 3;
  }
}

message NodeBinding {
  uint64 id = 1;
  string label = 2;
}

message EdgeBinding {
  uint64 id = 1;
  string edge_type = 2;
  uint64 from = 3;
  uint64 to = 4;
}

message PathBinding {
  repeated uint64 nodes = 1;
  repeated uint64 edges = 2;
  uint64 length = 3;
}

message PatternMatchStats {
  uint64 matches_found = 1;
  uint64 nodes_evaluated = 2;
  uint64 edges_evaluated = 3;
  bool truncated = 4;
}

message RowChunk {
  Row row = 1;
}

message UnifiedQueryResult {
  string description = 1;
  repeated UnifiedItem items = 2;
}

message UnifiedItem {
  string entity_type = 1;
  string key = 2;
  map<string, string> fields = 3;
  optional float score = 4;
}

message TableListResult {
  repeated string tables = 1;
}

message BlobResult {
  bytes data = 1;
}

message ArtifactInfo {
  string id = 1;
  string filename = 2;
  string content_type = 3;
  uint64 size = 4;
  string checksum = 5;
  uint64 chunk_count = 6;
  uint64 created = 7;
  uint64 modified = 8;
  string created_by = 9;
  repeated string tags = 10;
  repeated string linked_to = 11;
  map<string, string> custom = 12;
}

message ArtifactListResult {
  repeated string artifact_ids = 1;
}

message BlobStatsResult {
  uint64 artifact_count = 1;
  uint64 chunk_count = 2;
  uint64 total_bytes = 3;
  uint64 unique_bytes = 4;
  double dedup_ratio = 5;
  uint64 orphaned_chunks = 6;
}

message CheckpointListResult {
  repeated CheckpointInfo checkpoints = 1;
}

message CheckpointInfo {
  string id = 1;
  string name = 2;
  uint64 created_at = 3;
  bool is_auto = 4;
}

// === Chain Result Types ===

message ChainQueryResult {
  oneof result {
    ChainTransactionBegun transaction_begun = 1;
    ChainCommitted committed = 2;
    ChainRolledBack rolled_back = 3;
    ChainHistory history = 4;
    ChainSimilar similar = 5;
    ChainDrift drift = 6;
    ChainHeight height = 7;
    ChainTip tip = 8;
    ChainBlockInfo block = 9;
    ChainCodebookInfo codebook = 10;
    ChainTransitionAnalysis transition_analysis = 11;
    ChainConflictResolution conflict_resolution = 12;
    ChainMergeResult merge = 13;
  }
}

message ChainTransactionBegun {
  string tx_id = 1;
}

message ChainCommitted {
  string block_hash = 1;
  uint64 height = 2;
}

message ChainRolledBack {
  uint64 to_height = 1;
}

message ChainHistory {
  repeated ChainHistoryEntry entries = 1;
}

message ChainHistoryEntry {
  uint64 height = 1;
  string transaction_type = 2;
  optional bytes data = 3;
}

message ChainSimilar {
  repeated ChainSimilarItem items = 1;
}

message ChainSimilarItem {
  string block_hash = 1;
  uint64 height = 2;
  float similarity = 3;
}

message ChainDrift {
  uint64 from_height = 1;
  uint64 to_height = 2;
  float total_drift = 3;
  float avg_drift_per_block = 4;
  float max_drift = 5;
}

message ChainHeight {
  uint64 height = 1;
}

message ChainTip {
  string hash = 1;
  uint64 height = 2;
}

message ChainBlockInfo {
  uint64 height = 1;
  string hash = 2;
  string prev_hash = 3;
  uint64 timestamp = 4;
  uint64 transaction_count = 5;
  string proposer = 6;
}

message ChainCodebookInfo {
  string scope = 1;
  uint64 entry_count = 2;
  uint64 dimension = 3;
  optional string domain = 4;
}

message ChainTransitionAnalysis {
  uint64 total_transitions = 1;
  uint64 valid_transitions = 2;
  uint64 invalid_transitions = 3;
  float avg_validity_score = 4;
}

message ChainConflictResolution {
  string strategy = 1;
  uint64 conflicts_resolved = 2;
}

message ChainMergeResult {
  bool success = 1;
  uint64 merged_count = 2;
}

// === Spatial Result Types ===

message SpatialQueryResult {
  repeated SpatialItem items = 1;
}

message SpatialItem {
  string key = 1;
  float distance = 2;
  float x = 3;
  float y = 4;
  float width = 5;
  float height = 6;
}

// === Error Types ===

message ErrorInfo {
  ErrorCode code = 1;
  string message = 2;
  optional string details = 3;
}

enum ErrorCode {
  ERROR_CODE_UNSPECIFIED = 0;
  ERROR_CODE_INVALID_QUERY = 1;
  ERROR_CODE_NOT_FOUND = 2;
  ERROR_CODE_PERMISSION_DENIED = 3;
  ERROR_CODE_ALREADY_EXISTS = 4;
  ERROR_CODE_INTERNAL = 5;
  ERROR_CODE_UNAVAILABLE = 6;
  ERROR_CODE_INVALID_ARGUMENT = 7;
  ERROR_CODE_UNAUTHENTICATED = 8;
}

// === Blob Messages ===

message BlobUploadRequest {
  oneof request {
    BlobUploadMetadata metadata = 1;
    bytes chunk = 2;
  }
}

message BlobUploadMetadata {
  string filename = 1;
  optional string content_type = 2;
  optional string created_by = 3;
  repeated string tags = 4;
  repeated string linked_to = 5;
  map<string, string> custom = 6;
}

message BlobUploadResponse {
  string artifact_id = 1;
  uint64 size = 2;
  string checksum = 3;
}

message BlobDownloadRequest {
  string artifact_id = 1;
}

message BlobDownloadChunk {
  bytes data = 1;
  bool is_final = 2;
}

message BlobDeleteRequest {
  string artifact_id = 1;
}

message BlobDeleteResponse {
  bool success = 1;
}

message BlobMetadataRequest {
  string artifact_id = 1;
}

// === Health Messages ===

message HealthCheckRequest {
  optional string service = 1;
}

message HealthCheckResponse {
  ServingStatus status = 1;
}

enum ServingStatus {
  SERVING_STATUS_UNSPECIFIED = 0;
  SERVING_STATUS_SERVING = 1;
  SERVING_STATUS_NOT_SERVING = 2;
}

