// SPDX-License-Identifier: MIT OR Apache-2.0
//! Neumann Server binary entry point.

use std::sync::Arc;

use neumann_server::{NeumannServer, ServerConfig};
use parking_lot::RwLock;
use query_router::QueryRouter;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    // Initialize tracing
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::from_default_env()
                .add_directive("neumann_server=info".parse()?)
                .add_directive("query_router=info".parse()?)
                .add_directive("tower_http=debug".parse()?),
        )
        .init();

    // Load configuration from environment or defaults
    let mut config = ServerConfig::from_env()?;

    tracing::info!("Starting Neumann server on {}", config.bind_addr);

    // Create the query router
    let router = Arc::new(RwLock::new(QueryRouter::new()));

    // Initialize cluster mode if configured
    if let Some(ref cluster_config) = config.cluster {
        router.write().init_cluster_with_wal(
            &cluster_config.node_id,
            cluster_config.raft_bind_addr,
            &cluster_config.peers,
            &cluster_config.data_dir,
        )?;
        tracing::info!(
            "Cluster mode: {} listening on {}",
            cluster_config.node_id,
            cluster_config.raft_bind_addr,
        );
    }

    // Create and run the server
    let mut server = NeumannServer::new(router, config.clone());

    // Optionally attach a grokking experiment (NEUMANN_LEARN=1)
    if std::env::var("NEUMANN_LEARN").is_ok() {
        if config.web_addr.is_none() {
            config.web_addr = Some("127.0.0.1:9000".parse()?);
        }

        server = NeumannServer::new(Arc::new(RwLock::new(QueryRouter::new())), config)
            .with_relational_engine(Arc::new(relational_engine::RelationalEngine::new()))
            .with_vector_engine(Arc::new(vector_engine::VectorEngine::new()))
            .with_graph_engine(Arc::new(graph_engine::GraphEngine::new()));

        let grok = tensor_learn::GrokSession::new(tensor_learn::GrokConfig::default());
        server = server.with_grok(Arc::new(RwLock::new(grok)));

        tracing::info!("Grokking dashboard at http://127.0.0.1:9000/learn");
    }

    server.serve().await?;

    Ok(())
}

/// CLUSTER operations.
#[derive(Clone, Debug, PartialEq)]
pub enum ClusterOp {
    /// Connect to cluster: `CLUSTER CONNECT 'address'`
    Connect {
        /// Cluster address(es).
        addresses: Expr,
    },
    /// Disconnect from cluster: `CLUSTER DISCONNECT`
    Disconnect,
    /// Show cluster status: `CLUSTER STATUS`
    Status,
    /// List cluster nodes: `CLUSTER NODES`
    Nodes,
    /// Show current leader: `CLUSTER LEADER`
    Leader,
}

// =============================================================================
// Blob Storage Statements
// =============================================================================

/// BLOB command.
#[derive(Clone, Debug, PartialEq)]
pub struct BlobStmt {
    /// The blob operation to perform.
    pub operation: BlobOp,
}

/// BLOB operations.
#[derive(Clone, Debug, PartialEq)]
pub enum BlobOp {
    /// Initialize blob store: `BLOB INIT`
    Init,
    /// Store blob: `BLOB PUT 'filename' DATA` or `BLOB PUT 'filename' FROM 'path'`
    Put {
        /// File name for the blob.
        filename: Expr,
        /// Inline data content.
        data: Option<Expr>,
        /// Path to read data from.
        from_path: Option<Expr>,
        /// Additional options.
        options: BlobOptions,
    },
    /// Get blob: `BLOB GET 'artifact_id'` or `BLOB GET 'artifact_id' TO 'path'`
    Get {
        /// Artifact ID.
        artifact_id: Expr,
        /// Optional file path to write to.
        to_path: Option<Expr>,
    },
    /// Delete blob: `BLOB DELETE 'artifact_id'`
    Delete {
        /// Artifact ID.
        artifact_id: Expr,
    },
    /// Show blob info: `BLOB INFO 'artifact_id'`
    Info {
        /// Artifact ID.

        /// Bounding box x coordinate.
        x: Expr,
        /// Bounding box y coordinate.
        y: Expr,
        /// Bounding box width.
        width: Expr,
        /// Bounding box height.
        height: Expr,
    },
    /// Nearest centroid query: `SPATIAL NEAREST x y [LIMIT k]`
    Nearest {
        /// X coordinate of query point.
        x: Expr,
        /// Y coordinate of query point.
        y: Expr,
        /// Maximum results to return (defaults to 1 at execution).
        limit: Option<Expr>,
    },
    /// Count entries: `SPATIAL COUNT`
    Count,
}

// =============================================================================
// Unified Statements
// =============================================================================

/// FIND unified query.
#[derive(Clone, Debug, PartialEq)]
pub struct FindStmt {
    /// The find pattern.
    pub pattern: FindPattern,
    /// Optional WHERE filter.
    pub where_clause: Option<Box<Expr>>,
    /// Optional SIMILAR TO clause for vector similarity ranking.
    pub similar_to: Option<Expr>,
    /// Optional CONNECTED TO clause for graph connectivity constraint.
    pub connected_to: Option<Expr>,
    /// Items to return.
    pub return_items: Vec<SelectItem>,
    /// Maximum number of results.
    pub limit: Option<Box<Expr>>,
}

/// FIND pattern.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum FindPattern {
    /// Match nodes by label
    Nodes {
        /// Optional label filter.
        label: Option<Ident>,
    },
    /// Match edges by type
    Edges {
        /// Optional edge type filter.
        edge_type: Option<Ident>,
    },
    /// Match rows in a relational table: `FIND ROWS FROM table`
    Rows {
        /// Table name.
        table: Ident,
    },
    /// Match path pattern
    Path {
        /// Source node label.
        from: Option<Ident>,
        /// Edge type.
        edge: Option<Ident>,
        /// Target node label.
        to: Option<Ident>,
    },
}

/// ENTITY command.
#[derive(Clone, Debug, PartialEq)]
pub struct EntityStmt {
    /// The entity operation to perform.
    pub operation: EntityOp,
}

/// ENTITY operations.

    /// Connect entities: `ENTITY CONNECT 'from' -> 'to' : type`
    Connect {
        /// Source entity key.
        from_key: Expr,
        /// Target entity key.
        to_key: Expr,
        /// Edge type label.
        edge_type: Ident,
    },
    /// Batch create entities: `ENTITY BATCH CREATE [{key: 'k1', props...}, ...]`
    Batch {
        /// Entity definitions.
        entities: Vec<BatchEntityDef>,
    },
}

/// Batch entity definition for ENTITY BATCH CREATE.
#[derive(Clone, Debug, PartialEq)]
pub struct BatchEntityDef {
    /// Entity key.
    pub key: Expr,
    /// Entity properties.
    pub properties: Vec<Property>,
    /// Optional embedding vector.
    pub embedding: Option<Vec<Expr>>,
}

// =============================================================================
// Vault Statements
// =============================================================================

/// VAULT command.
#[derive(Clone, Debug, PartialEq)]
pub struct VaultStmt {
    /// The vault operation to perform.
    pub operation: VaultOp,
}

/// VAULT operations.
#[derive(Clone, Debug, PartialEq)]
pub enum VaultOp {
    /// Set a secret: `VAULT SET 'key' 'value'`
    Set {
        /// Secret key.
        key: Expr,
        /// Secret value.
        value: Expr,
    },
    /// Get a secret: `VAULT GET 'key'`
    Get {
        /// Secret key.
        key: Expr,
    },
    /// Delete a secret: `VAULT DELETE 'key'`
    Delete {
        /// Secret key.
        key: Expr,
    },
    /// List secrets: `VAULT LIST 'pattern'`
    List {

        /// Artifact ID.
        artifact_id: Expr,
    },
    /// Link blob to entity: `BLOB LINK 'artifact_id' TO entity`
    Link {
        /// Artifact ID.
        artifact_id: Expr,
        /// Entity to link to.
        entity: Expr,
    },
    /// Unlink blob from entity: `BLOB UNLINK 'artifact_id' FROM entity`
    Unlink {
        /// Artifact ID.
        artifact_id: Expr,
        /// Entity to unlink from.
        entity: Expr,
    },
    /// Get links: `BLOB LINKS 'artifact_id'`
    Links {
        /// Artifact ID.
        artifact_id: Expr,
    },
    /// Add tag: `BLOB TAG 'artifact_id' 'tag'`
    Tag {
        /// Artifact ID.
        artifact_id: Expr,
        /// Tag to add.
        tag: Expr,
    },
    /// Remove tag: `BLOB UNTAG 'artifact_id' 'tag'`
    Untag {
        /// Artifact ID.
        artifact_id: Expr,
        /// Tag to remove.
        tag: Expr,
    },
    /// Verify integrity: `BLOB VERIFY 'artifact_id'`
    Verify {
        /// Artifact ID.
        artifact_id: Expr,
    },
    /// Run garbage collection: `BLOB GC` or `BLOB GC FULL`
    Gc {
        /// Whether to run full GC.
        full: bool,
    },
    /// Repair blob storage: `BLOB REPAIR`
    Repair,
    /// Show blob statistics: `BLOB STATS`
    Stats,
    /// Set metadata: `BLOB META SET 'artifact_id' 'key' 'value'`
    MetaSet {
        /// Artifact ID.
        artifact_id: Expr,
        /// Metadata key.
        key: Expr,
        /// Metadata value.
        value: Expr,
    },
    /// Get metadata: `BLOB META GET 'artifact_id' 'key'`
    MetaGet {
        /// Artifact ID.
        artifact_id: Expr,
        /// Metadata key.
        key: Expr,
    },
}

/// Options for BLOB PUT.
#[derive(Clone, Debug, PartialEq, Default)]
pub struct BlobOptions {
    /// Content type
    pub content_type: Option<Expr>,
    /// Creator
    pub created_by: Option<Expr>,
    /// Entities to link
    pub link: Vec<Expr>,
    /// Tags to apply
    pub tag: Vec<Expr>,
}

/// BLOBS command (list/query blobs).
#[derive(Clone, Debug, PartialEq)]
pub struct BlobsStmt {
    /// The blobs query operation.
    pub operation: BlobsOp,
}

/// BLOBS operations.
#[derive(Clone, Debug, PartialEq)]

    GraphBatch(GraphBatchStmt),

    // === Cypher Graph Statements ===
    /// Cypher MATCH statement
    CypherMatch(crate::cypher::CypherMatchStmt),
    /// Cypher CREATE statement
    CypherCreate(crate::cypher::CypherCreateStmt),
    /// Cypher DELETE statement
    CypherDelete(crate::cypher::CypherDeleteStmt),
    /// Cypher MERGE statement
    CypherMerge(crate::cypher::CypherMergeStmt),

    /// Empty statement (just semicolons)
    Empty,
}

